            { q: "What is the recommended JWT token lifetime strategy?", opts: ["Long-lived access tokens for convenience", "Short-lived access tokens (15-60 min) with long-lived refresh tokens — limits damage from token theft", "Never expire tokens", "Same lifetime for both"], a: 1, exp: "Short access token lifetimes limit the window for token abuse. Refresh tokens enable transparent renewal without requiring re-login." },
            { q: "What is a shadow API?", opts: ["A backup API", "An undocumented, forgotten, or unauthorized API endpoint — a major security risk that's often unprotected", "A read-only API", "A test API"], a: 1, exp: "Shadow APIs accumulate through microservices proliferation and poor governance. They lack authentication, rate limiting, and monitoring — easy targets for attackers." },
            { q: "What is API rate limiting?", opts: ["Limiting API documentation length", "Restricting request volume per client to prevent abuse, DDoS, and ensure fair usage", "Limiting API response size", "Network bandwidth throttling"], a: 1, exp: "Rate limiting prevents credential stuffing (limit login attempts), DDoS (limit all requests), and API scraping (limit data extraction)." },
            { q: "What is API versioning strategy best practice?", opts: ["Never version APIs", "Use URL versioning (/api/v1/) for public APIs — clear, cacheable, and easy for clients to adopt", "Version with dates only", "Use headers for all versioning"], a: 1, exp: "URL versioning (/v1/, /v2/) is most visible and widely adopted for public APIs. Header versioning is cleaner but harder for clients to test and cache." }
